1. New file src/app/courses-link.tsx:

"use client";

import Link from "next/link";
import type { ReactNode } from "react";

// A link to the home page's Course grid. From other pages it's an ordinary <Link> to /#courses.
// On the home page, next/link won't scroll again to a hash that's already in the URL
// (and can push /#courses#courses), so scroll by hand. Next's own (patched) pushState keeps
// the router's state on the history entry, so Back still works.
export function CoursesLink({ className, children }: { className?: string; children: ReactNode }) {
  return (
    <Link
      href="/#courses"
      className={className}
      onNavigate={(event) => {
        const grid = document.getElementById("courses");
        if (window.location.pathname !== "/" || !grid) return;
        event.preventDefault();
        if (window.location.hash !== "#courses") window.history.pushState(null, "", "/#courses");
        grid.scrollIntoView();
        document.getElementById("courses-title")?.focus({ preventScroll: true });
      }}
    >
      {children}
    </Link>
  );
}

Why it's built this way:
- onNavigate runs only for a plain click or Enter that Link would route (link.js:56-59, 71-80), so Ctrl/Cmd-click still opens a new tab.
- Link has already called preventDefault on the click (link.js:70), so the browser doesn't also jump on its own.
- pushState runs before scrollIntoView, so Back returns to the position the reader was at before the click.

